import{_ as t,o as i,c as o,ag as r}from"./chunks/framework.D6W-aSwD.js";const w=JSON.parse('{"title":"3D View","description":"","frontmatter":{},"headers":[],"relativePath":"tr/qgc-user-guide/viewer_3d/viewer_3d.md","filePath":"tr/qgc-user-guide/viewer_3d/viewer_3d.md"}'),n={name:"tr/qgc-user-guide/viewer_3d/viewer_3d.md"};function s(a,e,l,h,d,u){return i(),o("div",null,e[0]||(e[0]=[r('<h1 id="_3d-view" tabindex="-1">3D View <a class="header-anchor" href="#_3d-view" aria-label="Permalink to &quot;3D View&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>The entire 3D View feature is a work in progress. You may hit various issues while using it.</p></div><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The 3D View is not available on Android, as rendering is not yet reliable across Android GPUs and drivers.</p></div><p>The 3D View is used to visualize and monitor the vehicle, the environment, and the planned mission in 3D. Most of the capabilities available in the <a href="./../fly_view/fly_view.html">Fly View</a> is also available in the 3D View.</p><p>You can use it to:</p><ul><li>To import and display the 3D map for any region of interest downloaded from the OpenStreetMap website (.osm file).</li><li>Display the vehicle along with its mission in 3D.</li><li>And most of the capabilities of the <a href="./../fly_view/fly_view.html">Fly View</a>, including: <ul><li>Run an automated <a href="./../fly_view/hud.html#preflight_checklist">pre-flight checklist</a>.</li><li>Arm the vehicle (or check why it won&#39;t arm).</li><li>Control missions: <a href="./../fly_view/hud.html#start_mission">start</a>, <a href="./../fly_view/hud.html#continue_mission">continue</a>, <a href="./../fly_view/hud.html#pause">pause</a>, and <a href="./../fly_view/hud.html#resume_mission">resume</a>.</li><li>Guide the vehicle to <a href="./../fly_view/hud.html#arm">arm</a>/<a href="./../fly_view/hud.html#disarm">disarm</a>/<a href="./../fly_view/hud.html#emergency_stop">emergency stop</a>, <a href="./../fly_view/hud.html#takeoff">takeoff</a>/<a href="./../fly_view/hud.html#land">land</a>, <a href="./../fly_view/hud.html#change_altitude">change altitude</a>, and <a href="./../fly_view/hud.html#rtl">return/RTL</a>.</li><li>Switch between a map view and a video view (if available)</li><li>Display video, mission, telemetry, and other information for the current vehicle, and also switch between connected vehicles.</li></ul></li></ul><h1 id="ui-overview" tabindex="-1">UI Overview <a class="header-anchor" href="#ui-overview" aria-label="Permalink to &quot;UI Overview&quot;">​</a></h1><p>The main elements of the 3D View are the same as the <a href="./../fly_view/fly_view.html">Fly View</a>, with an added 3D environment.</p><p><strong>Enabling the 3D View:</strong> The 3D View is disabled by default. To enable it, go to <strong>Settings &gt; Fly View</strong>, and under the <strong>3D View</strong> settings group, toggle the <strong>Enabled</strong> switch.</p><p>To open the 3D View, when you are in the <a href="./../fly_view/fly_view.html">Fly View</a>, select the 3D View icon from the toolbar on the left.</p><h2 id="view-controls" tabindex="-1">View Controls <a class="header-anchor" href="#view-controls" aria-label="Permalink to &quot;View Controls&quot;">​</a></h2><p>The camera controls work like Gazebo: gestures are anchored to the ground point under the cursor, so the spot you grab stays under the cursor while you pan, orbit, or zoom.</p><ul><li><p><strong>Mouse:</strong></p><ul><li><strong>Pan</strong>: Press and hold the left mouse button, then move the cursor. The ground point you grabbed follows the cursor.</li><li><strong>Orbit (rotate)</strong>: Press and hold the middle mouse button (scroll wheel), then move the cursor. The view rotates around the ground point under the cursor: dragging left/right changes heading (a full window width of drag is one full revolution), dragging up/down changes the viewing angle between top-down and near-horizontal.</li><li><strong>Orbit (trackpad-friendly)</strong>: Hold <strong>Shift</strong> and drag with the left button. This is useful on trackpads without a middle button.</li><li><strong>Zoom</strong>: Use the mouse wheel or trackpad scroll, or press and hold the right mouse button and drag up (zoom in) or down (zoom out). Zooming moves toward or away from the ground point under the cursor, keeping it fixed on screen.</li></ul></li><li><p><strong>Touchscreen:</strong></p><ul><li><strong>Pan</strong>: Tap and move with a single finger.</li><li><strong>Zoom</strong>: Pinch with two fingers, moving them together or apart.</li><li><strong>Rotate</strong>: Twist with two fingers. The view rotates around the ground point under the gesture, following your fingers.</li><li><strong>Tilt</strong>: Swipe up or down with two fingers held together. Swiping up tilts toward the horizon, swiping down toward a top-down view.</li></ul></li></ul><p>A <strong>scale bar</strong> is shown in the same position as in the Fly View (top of the view, next to the tool strip) and shows the ground distance covered on screen. In a perspective view the scale varies across the screen; the value shown is exact for the ground plane through the screen center.</p><p>To visualize the 3D map of a particular area in the 3D viewer, you have to download the .osm file of that area from the <a href="https://www.openstreetmap.org/#map=16/47.3964/8.5498" target="_blank" rel="noreferrer">OpenStreetMap</a> website and then import it through the <strong>3D View</strong> settings. More details on the <strong>3D View</strong> settings can be found in the next section.</p><p>If no OSM file is loaded, buildings are not shown, but the 3D View still displays the vehicle over a map-tile ground patch centered on the vehicle&#39;s home position, viewed from the side by default.</p><h1 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h1><p>You can change the settings of the 3D View from <strong>Application Settings</strong> -&gt;<strong>Fly View</strong> tab under the <strong>3D View</strong> settings group. The following properties can be modified in the 3D View settings group:</p><ul><li><strong>Enabled</strong>: To enable or disable the 3D View.</li><li><strong>3D Map File</strong>: The path to the .osm file of a region of interest to be visualized in the QGC. The .osm file can be uploaded by clicking on the <strong>Select File</strong> button. To clear the 3D View from the previously loaded .osm file, you can click on the <strong>Clear</strong> button.</li><li><strong>Average Building Level Height</strong>: This parameter determines the height of each storey of the buildings, as in .osm file sometimes the height of the buildings is specified in terms of the level/storey.</li><li><strong>Vehicle Altitude Bias</strong>: This refers to the bias in the altitude of vehicles and their missions with respect to the ground level. It is helpful in cases where the estimated altitude of the vehicle by its flight control is biased, as the relative altitude is currently used in the 3D View.</li></ul>',19)]))}const c=t(n,[["render",s]]);export{w as __pageData,c as default};
